<template>
  <div class="page-metric-backend">
    <div class="page-header">
      <h2>{{ t('settings.metricsBackend.title') }}</h2>
    </div>

    <!-- 当前状态 -->
    <el-card v-loading="loadingStatus" class="status-card">
      <template #header>
        <span>{{ t('settings.metricsBackend.currentStatus') }}</span>
      </template>
      <el-descriptions :column="2" border>
        <el-descriptions-item :label="t('settings.metricsBackend.currentBackend')">
          <el-tag :type="status?.current_backend === 'influxdb' ? 'primary' : 'success'">
            {{ status?.current_backend?.toUpperCase() }}
          </el-tag>
        </el-descriptions-item>
        <el-descriptions-item :label="t('settings.metricsBackend.healthStatus')">
          <el-tag :type="status?.healthy ? 'success' : 'danger'">
            {{ status?.healthy ? t('settings.metricsBackend.healthy') : t('settings.metricsBackend.unhealthy') }}
          </el-tag>
        </el-descriptions-item>
      </el-descriptions>
    </el-card>

    <!-- 配置信息 -->
    <el-card class="config-card">
      <template #header>
        <span>{{ t('settings.metricsBackend.configTitle') }}</span>
      </template>
      <el-tabs v-model="activeConfigTab">
        <el-tab-pane label="InfluxDB" name="influxdb">
          <el-form label-width="160px">
            <el-form-item label="URL">
              <el-input v-model="influxForm.url" disabled />
            </el-form-item>
            <el-form-item label="Org">
              <el-input v-model="influxForm.org" disabled />
            </el-form-item>
            <el-form-item label="Bucket">
              <el-input v-model="influxForm.bucket" disabled />
            </el-form-item>
            <el-form-item label="Token">
              <el-input v-model="influxForm.token" disabled type="password" show-password />
            </el-form-item>
          </el-form>
        </el-tab-pane>
        <el-tab-pane label="SQLite" name="sqlite">
          <el-form label-width="160px">
            <el-form-item :label="t('settings.metricsBackend.databaseUrl')">
              <el-input v-model="sqliteForm.databaseUrl" disabled />
            </el-form-item>
          </el-form>
        </el-tab-pane>
      </el-tabs>
    </el-card>

    <!-- 切换后端 -->
    <el-card class="switch-card">
      <template #header>
        <span>{{ t('settings.metricsBackend.switchBackend') }}</span>
      </template>
      <el-form label-width="120px">
        <el-form-item :label="t('settings.metricsBackend.targetBackend')">
          <el-radio-group v-model="targetBackend">
            <el-radio-button label="influxdb">InfluxDB</el-radio-button>
            <el-radio-button label="sqlite">SQLite</el-radio-button>
          </el-radio-group>
        </el-form-item>
        <el-form-item>
          <el-button
            type="primary"
            :loading="testing"
            :disabled="targetBackend === status?.current_backend"
            @click="handleTest"
          >
            {{ t('settings.metricsBackend.testConnection') }}
          </el-button>
          <el-button
            type="success"
            :loading="switching"
            :disabled="targetBackend === status?.current_backend"
            @click="handleSwitch"
          >
            {{ t('settings.metricsBackend.switchTo', { backend: targetBackend?.toUpperCase() }) }}
          </el-button>
        </el-form-item>
      </el-form>

      <el-alert
        v-if="testMessage"
        :title="testMessage"
        :type="testSuccess ? 'success' : 'error'"
        :closable="false"
        class="result-alert"
      />
    </el-card>

    <!-- 数据迁移 -->
    <el-card class="migrate-card">
      <template #header>
        <span>{{ t('settings.metricsBackend.historyMigration') }}</span>
      </template>
      <el-form label-width="120px">
        <el-form-item :label="t('settings.metricsBackend.sourceBackend')">
          <el-radio-group v-model="migrateForm.source">
            <el-radio-button label="influxdb">InfluxDB</el-radio-button>
            <el-radio-button label="sqlite">SQLite</el-radio-button>
          </el-radio-group>
        </el-form-item>
        <el-form-item :label="t('settings.metricsBackend.targetBackend')">
          <el-radio-group v-model="migrateForm.target">
            <el-radio-button label="influxdb">InfluxDB</el-radio-button>
            <el-radio-button label="sqlite">SQLite</el-radio-button>
          </el-radio-group>
        </el-form-item>
        <el-form-item>
          <el-button
            type="warning"
            :loading="migrating"
            :disabled="migrateForm.source === migrateForm.target"
            @click="handleMigrate"
          >
            {{ t('settings.metricsBackend.startMigration') }}
          </el-button>
        </el-form-item>
      </el-form>

      <el-alert
        v-if="migrateMessage"
        :title="migrateMessage"
        :type="migrateSuccess ? 'success' : 'error'"
        :closable="false"
        class="result-alert"
      />
    </el-card>
  </div>
</template>

<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import {
  getMetricBackendStatus,
  migrateMetricBackendData,
  switchMetricBackend,
  testBackendConnection,
  type MetricBackendStatus,
} from '@/api/metricBackend'
import { showError, showSuccess } from '@/utils/error'

const { t } = useI18n()

const loadingStatus = ref(false)
const testing = ref(false)
const switching = ref(false)
const migrating = ref(false)

const status = ref<MetricBackendStatus | null>(null)
const activeConfigTab = ref<'influxdb' | 'sqlite'>('influxdb')
const targetBackend = ref<'influxdb' | 'sqlite'>('sqlite')

const influxForm = reactive({
  url: '',
  org: '',
  bucket: '',
  token: '',
})

const sqliteForm = reactive({
  databaseUrl: '',
})

const testSuccess = ref(false)
const testMessage = ref('')

const migrateForm = reactive({
  source: 'influxdb' as 'influxdb' | 'sqlite',
  target: 'sqlite' as 'influxdb' | 'sqlite',
})

const migrateSuccess = ref(false)
const migrateMessage = ref('')

async function loadStatus() {
  loadingStatus.value = true
  try {
    status.value = await getMetricBackendStatus()
    activeConfigTab.value = status.value.current_backend
    targetBackend.value = status.value.current_backend === 'influxdb' ? 'sqlite' : 'influxdb'

    influxForm.url = status.value.config.influxdb_url
    influxForm.org = status.value.config.influxdb_org
    influxForm.bucket = status.value.config.influxdb_bucket
    influxForm.token = status.value.config.influxdb_token
    sqliteForm.databaseUrl = status.value.config.metric_sqlite_database_url
  } catch (error) {
    showError(error, t('settings.metricsBackend.loadFailed'))
  } finally {
    loadingStatus.value = false
  }
}

async function handleTest() {
  testing.value = true
  testMessage.value = ''
  try {
    const result = await testBackendConnection({ backend_type: targetBackend.value })
    testSuccess.value = result.success && result.healthy
    testMessage.value = result.message
    if (testSuccess.value) {
      showSuccess(t('settings.metricsBackend.testPassed'))
    } else {
      showError(new Error(result.message), t('settings.metricsBackend.testFailed'))
    }
  } catch (error) {
    testSuccess.value = false
    testMessage.value = t('settings.metricsBackend.testRequestFailed')
    showError(error, t('settings.metricsBackend.testFailed'))
  } finally {
    testing.value = false
  }
}

async function handleSwitch() {
  switching.value = true
  testMessage.value = ''
  try {
    const result = await switchMetricBackend({ backend_type: targetBackend.value })
    if (result.success) {
      showSuccess(t('settings.metricsBackend.switchedTo', { backend: result.current_backend.toUpperCase() }))
      await loadStatus()
    } else {
      showError(new Error(t('settings.metricsBackend.switchFailedShort')), t('settings.metricsBackend.switchFailed'))
    }
  } catch (error) {
    showError(error, t('settings.metricsBackend.switchFailed'))
  } finally {
    switching.value = false
  }
}

async function handleMigrate() {
  migrating.value = true
  migrateMessage.value = ''
  try {
    const result = await migrateMetricBackendData({
      source: migrateForm.source,
      target: migrateForm.target,
    })
    if (result.success) {
      migrateSuccess.value = true
      migrateMessage.value = t('settings.metricsBackend.migrateDone', { n: result.migrated_count })
      showSuccess(migrateMessage.value)
    } else {
      migrateSuccess.value = false
      migrateMessage.value = t('settings.metricsBackend.migrateFailed')
      showError(new Error(t('settings.metricsBackend.migrateFailed')), t('settings.metricsBackend.migrateFailed'))
    }
  } catch (error) {
    migrateSuccess.value = false
    migrateMessage.value = t('settings.metricsBackend.migrateRequestFailed')
    showError(error, t('settings.metricsBackend.migrateFailed'))
  } finally {
    migrating.value = false
  }
}

onMounted(() => {
  loadStatus()
})
</script>

<style scoped>
.page-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
}

.page-header h2 {
  margin: 0;
}

.status-card,
.config-card,
.switch-card,
.migrate-card {
  margin-bottom: 20px;
}

.result-alert {
  margin-top: 16px;
}
</style>
