import apiClient from './client'

export interface MetricBackendConfig {
  influxdb_url: string
  influxdb_org: string
  influxdb_bucket: string
  influxdb_token: string
  metric_sqlite_database_url: string
}

export interface MetricBackendStatus {
  current_backend: 'influxdb' | 'sqlite'
  healthy: boolean
  config: MetricBackendConfig
}

export interface TestBackendRequest {
  backend_type: 'influxdb' | 'sqlite'
  config?: Partial<MetricBackendConfig>
}

export interface TestBackendResponse {
  success: boolean
  backend_type: string
  healthy: boolean
  message: string
}

export interface SwitchBackendRequest {
  backend_type: 'influxdb' | 'sqlite'
}

export interface SwitchBackendResponse {
  success: boolean
  current_backend: string
}

export interface MigrateBackendRequest {
  source: 'influxdb' | 'sqlite'
  target: 'influxdb' | 'sqlite'
  source_config?: Partial<MetricBackendConfig>
  target_config?: Partial<MetricBackendConfig>
}

export interface MigrateBackendResponse {
  success: boolean
  migrated_count: number
}

export async function getMetricBackendStatus(): Promise<MetricBackendStatus> {
  const response = await apiClient.get<MetricBackendStatus>('/v1/admin/metric-backend')
  return response.data
}

export async function testBackendConnection(
  request: TestBackendRequest,
): Promise<TestBackendResponse> {
  const response = await apiClient.post<TestBackendResponse>(
    '/v1/admin/metric-backend/test',
    request,
  )
  return response.data
}

export async function switchMetricBackend(
  request: SwitchBackendRequest,
): Promise<SwitchBackendResponse> {
  const response = await apiClient.post<SwitchBackendResponse>(
    '/v1/admin/metric-backend/switch',
    request,
  )
  return response.data
}

export async function migrateMetricBackendData(
  request: MigrateBackendRequest,
): Promise<MigrateBackendResponse> {
  const response = await apiClient.post<MigrateBackendResponse>(
    '/v1/admin/metric-backend/migrate',
    request,
  )
  return response.data
}
